import type { Command } from "@axn-dev/core";

// Proper zsh #compdef script — intended to be placed in a fpath directory
// as _axn-dev so zsh autoloads it without any .zshrc modification.
export const ZSH_SCRIPT = `#compdef axn-dev

_axn_dev() {
  local -a completions
  completions=(\${(f)"$(axn-dev --complete \${words[@]} 2>/dev/null)"})
  compadd -a completions
}

_axn_dev
`.trimStart();

export const BASH_SCRIPT = `# axn-dev bash completion
# Generated by: axn-dev completion bash

_axn_dev_complete() {
  local IFS=$'\\n'
  COMPREPLY=( $(axn-dev --complete "\${COMP_WORDS[@]}" 2>/dev/null) )
}

complete -F _axn_dev_complete axn-dev
`.trimStart();

export class CompletionCommand implements Command {
  readonly name = "completion";
  readonly description = "Print shell completion script (zsh|bash)";

  complete(words: string[]): string[] {
    const cur = words[words.length - 1] ?? "";
    if (words.length === 3) {
      return ["zsh", "bash"].filter((s) => s.startsWith(cur) && s !== cur);
    }
    return [];
  }

  help(): string {
    return `
Usage: axn-dev completion <shell>

Print a shell completion script to stdout.

Shells:
  zsh   #compdef script for fpath-based autoloading
  bash  complete-based script

Preferred setup (no .zshrc modification needed after first time):
  axn-dev install --completion

Manual setup:
  axn-dev completion zsh > ~/.zsh/completions/_axn-dev
  axn-dev completion bash > ~/.bash_completion.d/axn-dev
`.trim();
  }

  async execute(args: string[]): Promise<void> {
    const shell = args[0];

    if (!shell || shell === "--help" || shell === "-h") {
      console.log(this.help());
      return;
    }

    if (shell === "zsh") {
      process.stdout.write(ZSH_SCRIPT);
    } else if (shell === "bash") {
      process.stdout.write(BASH_SCRIPT);
    } else {
      throw new Error(`Unknown shell '${shell}'. Supported: zsh, bash`);
    }
  }
}
